import{_ as a,o,c,a0 as i}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /adopt","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/adopt.md","filePath":"references/skills/adopt.md"}'),t={name:"references/skills/adopt.md"};function n(l,e,d,s,r,h){return o(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="skill-adopt" tabindex="-1">Skill: <code>/adopt</code> <a class="header-anchor" href="#skill-adopt" aria-label="Permalink to &quot;Skill: `/adopt`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>adopt</code> (hoặc <code>/legacy-adopt</code>)</p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi quét toàn hệ thống legacy: <code>/adopt</code> (hoặc <code>/legacy-adopt</code>)</li><li>Gọi quét phạm vi ứng dụng/module legacy cụ thể: <code>/adopt &quot;Customer App&quot;</code> hoặc <code>/adopt admin-fe</code></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc <code>legacy-repos.local.json</code> (hoặc <code>platform-repos.local.json</code>) để xác định các repos/dự án legacy.</li><li>Quét qua cấu trúc file code cũ (Routers, Controllers, View/Page Components, Service Interfaces).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Khởi tạo duy nhất file chỉ mục <code>adoption-inventory.md</code> nằm ngay ở thư mục gốc (workspace root).</li><li>Liệt kê dạng bullet list (không checkbox, không ghi chi tiết spec) định danh danh mục: <ul><li>Surfaces (Bề mặt hệ thống)</li><li>Modules (<code>CMP-*</code>)</li><li>Screens (<code>W-*</code>) &amp; APIs (<code>API-*</code>) kèm đường dẫn file code cũ tương ứng (<code>ID -&gt; Legacy File Path</code>)</li><li>Cross-Flow Candidates (<code>FLOW-*</code>)</li></ul></li><li>Cuối file tổng hợp danh sách gợi ý Handoff Prompts cho bước tiếp theo.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Dùng để lập <strong>Bản đồ chỉ mục &amp; Mã hóa ID (Index &amp; Mapping Directory)</strong> cho dự án Legacy.</li><li>Giải quyết bài toán không ai có thời gian khảo cổ 100% dự án legacy. Đóng vai trò làm bản tra cứu giúp Member tìm nhanh ID của chức năng cần làm và file code cũ tương ứng.</li><li>Khi Member cần nâng cấp/sửa lỗi Chức năng A, Member tra <code>adoption-inventory.md</code> tại root để lấy ID (ví dụ <code>W-AD-AUTH-001</code>), sau đó gọi lệnh khảo cổ đi kèm <code>/legacy</code> (<code>/docs-hub /legacy /spec W-AD-AUTH-001</code>).</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Kích hoạt sau khi cài đặt hoặc bắt đầu tiếp cận dự án legacy: <code>/adopt</code>.</li><li>Khi khảo cổ chi tiết từng chức năng: Gọi kèm modifier <code>/legacy</code> với các skill <code>/surfaces</code>, <code>/module</code>, <code>/spec</code>, <code>/business-process</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/adopt</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const g=a(t,[["render",n]]);export{u as __pageData,g as default};
